// TunableRegistration takes an initializer list: expand the family's names into one.
template <size_t... I>
void register_names(const char* kernel, const char* const* m, std::index_sequence<I...>) {
  lx::TunableRegistration(kernel, {m[I]...});
}
template <int N = 1>
void register_n(const char* kernel, const char* const* m, int n) {
  if (n == N) register_names(kernel, m, std::make_index_sequence<N>{});
  else if constexpr (N < 16) register_n<N + 1>(kernel, m, n);
}

template <int kKind, int kArch>
struct Registered {
  Registered() {
    int n = 0;
    const Variant* v = Family<kKind, kArch>::variants(n);
    const char* names[16] = {};
    for (int i = 0; i < n && i < 16; ++i) names[i] = v[i].name;
    register_n(Family<kKind, kArch>::name(), names, n);
  }
};
const Registered<kBF16, 80> reg_bf16;
const Registered<kI8, 80> reg_i8;
const Registered<kF8, 89> reg_f8_89;
const Registered<kF8, 120> reg_f8_120;
const Registered<kF4, 120> reg_f4;
const Registered<kW8I8, 80> reg_w8i8;
const Registered<kW8F8, 80> reg_w8f8_80;
const Registered<kW8F8, 120> reg_w8f8_120;
const Registered<kW4A16, 80> reg_w4a16;
const Registered<kW4A8, 120> reg_w4a8;

// The default tile when the tuner has no entry: the variant measured fastest on an RTX 5070 Ti at the
// nearest of Praxis's shapes (N = 256 to 10304, M = 64 to 8192; bench/tune_gemm_w.py). The W8A16 and
// W4A16 kernels are bound by expanding the weight to bf16, so the narrow tile, which expands each weight
// once per 32 rows on a single warp row, wins at every shape. The others want CTAs enough to fill the GPU
// at small M, and the largest tiles once there are plenty.
const char* default_tile(int kind, int M, int N) {
  if (kind == kW8I8 || kind == kW8F8 || kind == kW4A16) return "32x128_w1x4_s4_k128";
  if (kind == kW4A8) {
    // One CTA of each W4A8 tile fits an SM, and once the GPU is full they run at about 74, 81 and 86
    // TFLOPS: the pick is the fewest waves of tiles, weighted by that rate, which matches the measured
    // best at every Praxis shape from M = 64 to 8192.
    static const int sms = [] {
      int dev = 0, n = 0;
      hipGetDevice(&dev);
      hipDeviceGetAttribute(&n, hipDeviceAttributeMultiprocessorCount, dev);
      return n > 0 ? n : 1;
    }();
    struct Option {
      const char* name;
      int bm;
      float rate;
    };
    const Option options[] = {{"32x128_w1x4_s4_k128", 32, 74.0f},
                              {"64x128_w2x4_s4_k128", 64, 81.0f},
                              {"128x128_w2x4_s3_k128", 128, 86.0f}};
    const char* best = options[0].name;
    float best_cost = 0.0f;
    for (const Option& o : options) {
      const int tiles = (M + o.bm - 1) / o.bm * ((N + 127) / 128);
      const float cost = static_cast<float>((tiles + sms - 1) / sms) * o.bm / o.rate;
      if (best_cost == 0.0f || cost < best_cost) best = o.name, best_cost = cost;
    }
    return best;
  }
  const bool f4 = kind == kF4;
  if (M <= 128) {
    if (N >= 4096 || (M > 64 && N >= 3072)) return f4 ? "64x128_w2x4_s3_k64" : "64x128_w2x4_s4_k64";
    return f4 ? "32x128_w1x4_s4_k64" : "32x128_w1x4_s4_k128";
  }
  if (M <= 512) {
    if (N >= 4096) return f4 ? "64x128_w2x4_s3_k64" : "128x128_w2x2_s3_k64";
    if (N >= 2048) return f4 ? "64x128_w2x4_s3_k64" : "64x128_w2x4_s4_k64";
    return f4 ? "32x128_w1x4_s4_k64" : "32x128_w1x4_s4_k128";
  }
  if (M <= 2048) {
    if (N >= 4096) return f4 ? "128x256_w2x4_s3_k64" : "128x128_w2x2_s3_k64";
    if (N >= 2048) return f4 ? "256x128_w4x2_s3_k64" : "256x128_w4x2_s4_k64";
    if (N >= 768) return f4 ? "128x128_w2x4_s3_k64" : "128x128_w2x4_s3_k64";
    return f4 ? "32x128_w1x4_s4_k64" : "32x128_w1x4_s4_k128";
  }
  return f4 ? "256x128_w4x2_s3_k64" : "128x128_w2x2_s3_k64";
}

// Small problems on sm_90+: the 32x128 tile split along K over a cluster of 2 or 4 CTAs when its tiles
// alone would leave SMs idle (measured, bench/tune_gemm_w.py: at most one CTA per SM after the split).
// The kernels that expand weights in the mainloop (W8A16, W4A16, W4A8) are bound by that arithmetic and
// gain from any more CTAs (up to 2.7x at M = 16), even with a couple of K tiles each. The homogeneous
// kinds are reading weights at small M and gain up to ~25%, but only while each CTA's K loop stays long
// against the cluster's sum: 4-way from 8 K tiles each with a handful of tiles (16 each up to 17 tiles),
// 2-way from 8 each up to 24 tiles and 16 each up to 35; past that a split costs up to 11% (measured on
// the RTX 5070 Ti, int8, fp8 and fp4, M 16 to 96, N 1024 to 4096, K 1024 to 8192). A split also makes a
// row's bits depend on M (kernels.h), so it is used only where it pays.
int split_for(int kind, int tiles, int k_tiles, int arch) {
  if (arch < 90) return 1;
  const bool mixed = kind == kW8I8 || kind == kW8F8 || kind == kW4A16 || kind == kW4A8;
  if (mixed) {
    if (tiles <= 17 && k_tiles >= 8) return 4;
    if (tiles <= 35 && k_tiles >= 4) return 2;
    return 1;
  }
  if (k_tiles >= 64 ? tiles <= 17 : (tiles <= 8 && k_tiles >= 32)) return 4;
  if (k_tiles >= 32 ? tiles <= 35 : (tiles <= 24 && k_tiles >= 16)) return 2;
  return 1;
}

template <int kKind, int kArch>
int run_family(const DenseProb::Params& pp, const DenseEpi::Params& ep, hipStream_t s) {
  int n = 0;
  const Variant* v = Family<kKind, kArch>::variants(n);
  const int arch = lx_arch();
  int pick = lx_tune_get(Family<kKind, kArch>::name(), pp.M, pp.N, pp.K);
  const int lds = lx_lds_limit();
  if (pick < 0 || pick >= n || v[pick].min_arch > arch || v[pick].smem > lds) {
    const char* want = default_tile(kKind, pp.M, pp.N);
    pick = 0;
    for (int i = 0; i < n; ++i)
      if (!std::strcmp(v[i].name, want)) pick = i;
    // A tile whose LDS does not fit this device cannot launch: take the first one that does.
    if (v[pick].smem > lds)
      for (int i = 0; i < n; ++i)
        if (v[i].smem <= lds && v[i].split == 1) {
          pick = i;
          break;
        }
    const int k_tile = lx::tc::Config<kKind, kArch, 32, 128, 1, 4, 4, (kKind == kF4 ? 64 : 128)>::kKTile;
    const int tiles = ((pp.M + 31) / 32) * ((pp.N + 127) / 128);
    const int split = v[pick].bm == 32 ? split_for(kKind, tiles, (pp.K + k_tile - 1) / k_tile, arch) : 1;
    for (int i = 0; split > 1 && i < n; ++i)
      if (v[i].split == split && v[i].bm == 32) pick = i;
  }
  return v[pick].fn(pp, ep, s);
}

bool aligned16(const void* p) { return (reinterpret_cast<uintptr_t>(p) & 15) == 0; }

}  // namespace

extern "C" int64_t lx_gemm_workspace_bytes(int M, int K, lx_math math) {
  if (M <= 0 || K <= 0) return 0;
  return act_layout(M, K, math).total;
}

extern "C" int lx_gemm_w(const void* x, lx_dtype x_dtype, int ld_x, const lx_weight* w, lx_math math, const void* bias,
                         lx_dtype bias_dtype, void* y, lx_dtype y_dtype, int ld_y, int M, int N, int K, float alpha,
                         float beta, void* workspace, void* stream) {
  if (M < 0 || N < 0 || K <= 0 || ld_x < K || ld_y < N || !w) return static_cast<int>(hipErrorInvalidValue);
  if (M == 0 || N == 0) return 0;
  if (!x || !y || !w->data) return static_cast<int>(hipErrorInvalidValue);
  if ((x_dtype != LX_F32 && x_dtype != LX_BF16) || (y_dtype != LX_F32 && y_dtype != LX_BF16) ||
      (bias && bias_dtype != LX_F32 && bias_dtype != LX_BF16))
    return static_cast<int>(hipErrorInvalidValue);
  auto s = static_cast<hipStream_t>(stream);
  const int arch = lx_arch();
  const bool sm120 = arch >= 120 && arch < 130;
  if (math < LX_MATH_BF16 || math > LX_MATH_FP4) return static_cast<int>(hipErrorInvalidValue);
  const int kind = kind_for(math, w->type, arch);
  if (kind < 0) return static_cast<int>(hipErrorNotSupported);
  if (w->type != LX_W_BF16 && !w->scale) return static_cast<int>(hipErrorInvalidValue);

  // Plain BF16: cuBLASLt, at the bf16 peak, when its bias rules fit (bf16 bias); x converted if f32.
  const ActLayout lay = act_layout(M, K, math);
  uint8_t* ws = static_cast<uint8_t*>(workspace);
  if (kind == kBF16 && (!bias || bias_dtype == LX_BF16)) {
    if (x_dtype == LX_F32) {
      if (!ws) return static_cast<int>(hipErrorInvalidValue);
      const int ld = static_cast<int>(lay.ld_q / 2);
      if (int e = lx_copy2d(x, LX_F32, ld_x, ws, LX_BF16, ld, M, K, stream)) return e;
      return lx_gemm_bf16(ws, ld, w->data, bias, y, y_dtype, ld_y, M, N, K, alpha, beta, stream);
    }
    return lx_gemm_bf16(x, ld_x, w->data, bias, y, y_dtype, ld_y, M, N, K, alpha, beta, stream);
  }

  // The tensor-core kernels read 16-byte chunks of rows: see k_ok.
  const int wbits = weight_bits(w->type);
  if (!k_ok(kind, w->type, K) || !aligned16(w->data)) return static_cast<int>(hipErrorNotSupported);

  DenseProb::Params pp{};
  pp.M = M;
  pp.N = N;
  pp.K = K;
  pp.b = static_cast<const uint8_t*>(w->data);
  pp.ldb = static_cast<int64_t>(K) * wbits / 8;
  pp.b_global = w->type == LX_W_NVFP4 ? w->global : 1.0f;
  if (w->type == LX_W_INT8 || w->type == LX_W_FP8) pp.b_scale = static_cast<const float*>(w->scale);
  if (w->type == LX_W_NVFP4) {
    pp.b_sf = static_cast<const uint8_t*>(w->scale);
    pp.ld_bsf = K / 16;
  }

  // Operand A: bf16 as given when aligned, else a bf16 copy; otherwise quantized per token.
  const bool a_bf16 = kind == kBF16 || kind == kW8I8 || kind == kW8F8 || kind == kW4A16;
  if (a_bf16) {
    if (x_dtype == LX_BF16 && aligned16(x) && (static_cast<int64_t>(ld_x) * 2) % 16 == 0) {
      pp.a = static_cast<const uint8_t*>(x);
      pp.lda = static_cast<int64_t>(ld_x) * 2;
    } else {
      if (!ws) return static_cast<int>(hipErrorInvalidValue);
      if (int e = lx_copy2d(x, x_dtype, ld_x, ws, LX_BF16, static_cast<int>(lay.ld_q / 2), M, K, stream)) return e;
      pp.a = ws;
      pp.lda = lay.ld_q;
    }
  } else {
    if (!ws) return static_cast<int>(hipErrorInvalidValue);
    const lx_math qmath = act_math(kind);
    const ActLayout ql = act_layout(M, K, qmath);
    if (int e = lx_quantize_act(x, x_dtype, ld_x, qmath, ws + ql.q_off, static_cast<int>(ql.ld_q),
                                reinterpret_cast<float*>(ws + ql.scale_off), ws + ql.bs_off, static_cast<int>(ql.ld_bs),
                                M, K, stream))
      return e;
    pp.a = ws + ql.q_off;
    pp.lda = ql.ld_q;
    pp.a_scale = reinterpret_cast<const float*>(ws + ql.scale_off);
    pp.a_sf = ws + ql.bs_off;
    pp.ld_asf = ql.ld_bs;
  }

  DenseEpi::Params ep{};
  ep.y = y;
  ep.ld_y = ld_y;
  ep.y_bf16 = y_dtype == LX_BF16;
  ep.pair_ok = ld_y % 2 == 0 && (reinterpret_cast<uintptr_t>(y) & (ep.y_bf16 ? 3 : 7)) == 0;
  ep.bias = bias;
  ep.bias_bf16 = bias_dtype == LX_BF16;
  ep.alpha = alpha;
  ep.beta = beta;

  switch (kind) {
    case kBF16: return run_family<kBF16, 80>(pp, ep, s);
    case kI8: return run_family<kI8, 80>(pp, ep, s);
    case kF8: return sm120 ? run_family<kF8, 120>(pp, ep, s) : run_family<kF8, 89>(pp, ep, s);
    case kF4: return run_family<kF4, 120>(pp, ep, s);
    case kW8I8: return run_family<kW8I8, 80>(pp, ep, s);
    case kW8F8: return sm120 ? run_family<kW8F8, 120>(pp, ep, s) : run_family<kW8F8, 80>(pp, ep, s);
    case kW4A16: return run_family<kW4A16, 80>(pp, ep, s);
    default: return run_family<kW4A8, 120>(pp, ep, s);
  }
}
